  let opt=!!x.opt;document.querySelectorAll('#seO button').forEach(b=>b.onclick=()=>{opt=b.dataset.v=='1';document.querySelectorAll('#seO button').forEach(c=>c.classList.toggle('on',c===b))});
  $('scrim').onclick=$('seX').onclick=close;
  $('seMic').onclick=()=>listen(v=>{const t=spoken(v).replace(/[.!?]+$/,'').trim();if(t)$('seN').value=t.charAt(0).toUpperCase()+t.slice(1)},$('seN'),'Sprich den Artikel neu');
  $('seDel').onclick=()=>{const ss=JSON.stringify(sh.items);sh.items=sh.items.filter(i=>i.id!=id);save();close();tell('Entfernt.',()=>{sh.items=JSON.parse(ss);save();render()})};
  $('seS').onclick=()=>{const n=$('seN').value.trim();if(!n){$('seN').focus();return}const pv=pNum($('seP').value),k=n.toLowerCase(),renamed=n!=x.n;
    x.n=n.charAt(0).toUpperCase()+n.slice(1);{const g=$('seG')&&$('seG').value;if(g&&(g!=shopGrp(x)||(sh.grp&&sh.grp[k]))){sh.grp=sh.grp||{};sh.grp[k]=g}}x.q=Math.max(1,Math.min(99,parseInt($('seQ').value)||1));x.unit=$('seU').value.trim();x.opt=opt;
    if(!isNaN(pv)&&pv>0){if(pv!==x.p||renamed){x.p=pv;x.est=false;sh.prices[k]=pv;phAdd(k,pv);if(sh.unk)delete sh.unk[k];shopMatch()}}else if(renamed){const f=shopKnown(k);x.p=f?f.p:0;x.est=f?f.est:false;sh.unk=sh.unk||{};if(!f)sh.unk[k]={n:x.n,t:Date.now()}}else if($('seP').value.trim()===''){x.p=0;x.est=false}
    save();close();tell('Gespeichert.',0,'nod',1)};
