   $('sheetRoot').innerHTML=`<div class="scrim" id="scrim"></div><div class="sheet" role="dialog" aria-label="Abo"><div class="sheet-h"><button id="abX">Abbrechen</button><b>${isNew?(aboKind(r)=='vertrag'?'Neuer Vertrag':'Neues Abo'):(aboKind(r)=='vertrag'?'Vertrag bearbeiten':'Abo bearbeiten')}</b><button id="abS" style="font-weight:600">Sichern</button></div>
   <div class="sheet-b"><div class="seg" id="abKd">${[["abo","Abo"],["vertrag","Vertrag"]].map(([v,l])=>`<button class="${aboKind(r)==v?"on":""}" data-v="${v}">${l}</button>`).join("")}</div><div class="group">
    <div class="cell plain"><label for="abN">Name</label><input id="abN" value="${esc(r.n)}" placeholder="z. B. Netflix"></div>
    <div class="cell plain"><label for="abP">Anbieter</label><input id="abP" value="${esc(c.prov||'')}" placeholder="optional"></div>
    <div class="cell plain"><label for="abA">Kosten</label><input id="abA" inputmode="decimal" value="${r.a?String(r.a).replace('.',','):''}" placeholder="€"></div>
    <div class="cell plain"><label for="abE">Rhythmus</label><select id="abE">${[[1,'monatlich'],[2,'alle 2 Monate'],[3,'vierteljährlich'],[6,'halbjährlich'],[12,'jährlich']].map(([v,l])=>`<option value="${v}" ${(r.every||1)==v?'selected':''}>${l}</option>`).join('')}</select></div>
    <div class="cell plain"><label for="abD">Abbuchung am</label><select id="abD">${Array.from({length:31},(_,k)=>`<option value="${k+1}" ${r.day==k+1?'selected':''}>${k+1}.</option>`).join('')}</select></div>
    <div class="cell plain"><label for="abB">Konto</label><select id="abB">${ALL.filter(a=>!isTabu(a)).map(a=>`<option ${r.b==a?'selected':''}>${esc(a)}</option>`).join('')}</select></div>
    <div class="cell plain"><label for="abC">Kategorie</label><select id="abC">${cs.map(k=>`<option ${r.c==k[0]?'selected':''}>${esc(k[0])}</option>`).join('')}${cs.some(k=>k[0]==r.c)?'':`<option selected>${esc(r.c||'Abos')}</option>`}</select></div>
    <div class="cell plain"><label for="abPa">Pausiert</label><span style="flex:1"></span><input id="abPa" type="checkbox" class="switch" ${r.paused?'checked':''}></div></div>
   <div class="sh" style="padding:0">Laufzeit & Kündigung</div><div class="group">
    <div class="cell plain"><label for="abK">Kündigungsfrist hinterlegen</label><span style="flex:1"></span><input id="abK" type="checkbox" class="switch" ${hasK?'checked':''}></div>
    ${hasK?`<div class="cell plain"><label for="abNx">Nächstes Vertragsende</label><input id="abNx" type="date" value="${c.next||''}"></div>
     <div class="cell plain"><label>Kündigungsfrist</label>${per('abF',c.notice)}</div>
     <div class="cell plain"><label for="abAu">Verlängert sich automatisch</label><span style="flex:1"></span><input id="abAu" type="checkbox" class="switch" ${c.auto?'checked':''}></div>
     <div class="cell plain"><label>Verlängerung um</label>${per('abR',c.renew)}</div>
     <div class="cell plain"><label for="abCa">Schon gekündigt</label><span style="flex:1"></span><input id="abCa" type="checkbox" class="switch" ${c.state=='cancelled'?'checked':''}></div>`:''}</div>
   
   <div class="note" id="abErr" style="padding:0;color:var(--bad)"></div>
   ${isNew?'':'<button class="btn soft" id="abNo">Kein Abo, aus dem Radar nehmen</button><button class="btn danger" id="abDel">Dauerauftrag löschen</button>'}</div></div>`;
