function shParts(tot,by,f){const o={},n=f.length;if(!n)return o;const c=Math.round(tot*100),each=Math.floor(c/n);f.forEach(id=>o[id]=each);o[f.includes(by)?by:f[0]]+=c-each*n;Object.keys(o).forEach(k=>o[k]/=100);return o}
