const HG=[['essen','Essen & Trinken','fork','#E2725B'],['wohnen','Wohnen & Haushalt','home','#3B82F6'],['mobil','Mobilität','bus','#14A3A3'],['gesund','Gesundheit & Pflege','heartpulse','#E11D74'],['freizeit','Freizeit & Genuss','ticket','#8B5CF6'],['shop','Shopping','bag','#F08C2E'],['vertrag','Verträge & Finanzen','receipt','#64748B'],['sonst','Sonstiges','dot','#9CA3AF']];
const HGI=Object.fromEntries(HG.map(x=>[x[0],x]));
const ICG2HG={'Einnahmen':'sonst','Verträge & Abgaben':'vertrag','Essen & Trinken':'essen','Wohnen & Haushalt':'wohnen','Mobilität':'mobil','Gesundheit & Pflege':'gesund','Kleidung & Schmuck':'shop','Freizeit & Sport':'freizeit','Reisen':'freizeit','Familie & Soziales':'freizeit','Technik & Medien':'shop','Finanzen & Verträge':'vertrag','Arbeit & Bildung':'sonst','Sonstiges':'sonst'};
function hgOf(b,c){const k=(S.catHG||{})[b+'|'+c];if(k&&HGI[k])return k;const n=String(c||'').toLowerCase();
  if(/lebensm|essen|restaurant|café|cafe|bäck|kantine|liefer|snack|getränk/.test(n))return 'essen';if(/miete|haushalt|wohn|strom|nebenk|möbel|garten/.test(n))return 'wohnen';if(/mobil|auto|bahn|tank|öpnv|taxi|fahr/.test(n))return 'mobil';
  if(/gesund|arzt|apothe|drogerie|friseur|beauty|pflege|kosmet/.test(n))return 'gesund';if(/freizeit|hobby|reise|urlaub|kino|sport|geschenk|ausgehen/.test(n))return 'freizeit';if(/shopping|kleidung|technik|mode/.test(n))return 'shop';
  if(/versich|vertrag|abo|steuer|kredit|gebühr|bank|spar/.test(n))return 'vertrag';const ic=((cats(b)||[]).find(x=>x[0]==c)||[])[1];if(ic){const g=ICGROUPS.find(([,ks])=>ks.includes(ic));if(g)return ICG2HG[g[0]]||'sonst'}return 'sonst'}
function hgSection(p,kf){const by={},tot0={v:0};RX().forEach(e=>{if(!inP(e,p)||isPlan(e)||e.type!='out'||e.corr||isTabu(e.b)||!kOk(e,kf))return;const g=hgOf(e.b,e.c);by[g]=(by[g]||0)+e.a;tot0.v+=e.a});const L=HG.filter(x=>by[x[0]]).sort((a,b)=>by[b[0]]-by[a[0]]);if(!L.length)return '';const mx=by[L[0][0]];
  return `<div class="sec"><div class="sh"><span>Nach Bereichen · alle Konten</span><span style="text-transform:none">${eur0(tot0.v)}</span></div><div class="group">${L.map(([k,n,ic,col])=>`<div class="cell plain hgrow"><div class="ico" style="background:color-mix(in srgb,${col} 16%,transparent);color:${col}">${I(ic,16)}</div><div class="t"><div>${n}</div><div class="hgbar"><i style="width:${(by[k]/mx*100).toFixed(0)}%;background:${col}"></i></div></div><div class="v">${eur0(by[k])}<div class="s">${Math.round(by[k]/tot0.v*100)} %</div></div></div>`).join('')}</div><div class="note">Fasst gleiche Bereiche über Flow, Gönn dir, Sinking Funds und das Eingangskonto zusammen. Zuordnung änderst du unter Einstellungen › Kategorien.</div></div>`}
