  document.querySelectorAll('[data-fcs]').forEach(inp=>inp.oninput=()=>{const k=inp.dataset.fcs,v=+inp.value,cur=+inp.dataset.cur;if(Math.abs(v-cur)<1)delete FCS[k];else FCS[k]=v;const lb=$('fcv-'+k.replace(/[^a-z0-9]/gi,'_'));if(lb)lb.innerHTML=eur0(v)+(Math.abs(v-cur)>=1?` <small>(${v>cur?'+':'−'}${eur0(Math.abs(v-cur))})</small>`:'');cancelAnimationFrame(raf);raf=requestAnimationFrame(()=>{tc.innerHTML=tresorChartHtml()})});
