  const PAL=['var(--accent)','var(--out,var(--bad))','var(--in,var(--ok))','#F08C2E'],mk=yrK=='q'?'v':yrK,mon=yrSel.map((y,j)=>{const D=R.find(r=>r.y==y).D,pts=Array.from({length:12},(_,m)=>{const d=D.ms.find(x=>x.m==m);return d?d[mk]:null});return{y,pts,col:PAL[j%4]}});
